/// <summary>
/// CB223_PalletRounding
/// </summary>
class METPalletRoundingPolicySearchParameters
{
    private ItemId          itemId;
    private CustAccount     custAccount;
    private InventSiteId    inventSiteId;

    //Following variables are required during Rounding Threshold check. 
    //Even when the certain policy is identified dring the search but does not pass the threshold rounding percentage, search should fallback and continue finding for the Layer type
    private SalesQty salesQtySum;
    private SalesUnit salesUnit;
    private InventDimId inventDimId;

}

Method.Source:
/// <summary>
/// Construct method
/// </summary>
/// <returns>Instance of <c>METPalletRoundingPolicySearchParameters</c></returns>
public static METPalletRoundingPolicySearchParameters construct()
{
    return new METPalletRoundingPolicySearchParameters();
}

/// <summary>
/// Parm method for item number
/// </summary>
/// <param name = "_itemId">Item number</param>
/// <returns>Item number</returns>
final public ItemId parmItemId(ItemId _itemId = itemId)
{
    itemId = _itemId;
    return itemId;
}

/// <summary>
/// Parm method for customer account
/// </summary>
/// <param name = "_custAccount">Customer account</param>
/// <returns>Customer account</returns>
final public CustAccount parmCustAccount(CustAccount _custAccount = custAccount)
{
    custAccount = _custAccount;
    return custAccount;
}

/// <summary>
/// Parm method for inventory site id
/// </summary>
/// <param name = "_inventSiteId">Inventory site id</param>
/// <returns>Inventory site id</returns>
final public InventSiteId parmInventSiteId(InventSiteId _inventSiteId = inventSiteId)
{
    inventSiteId = _inventSiteId;
    return inventSiteId;
}

/// <summary>
/// Parm method for summed sales quantity of lines with Item, Site combination
/// </summary>
/// <param name = "_salesQtySum">Sales quantity</param>
/// <returns>Sales quantity</returns>
final public SalesQty parmSalesQtySum(SalesQty _salesQtySum = salesQtySum)
{
    salesQtySum = _salesQtySum;
    return salesQtySum;
}

/// <summary>
/// Parm method for sales line unit
/// </summary>
/// <param name = "_salesUnit">Sales unit</param>
/// <returns>Sales unit</returns>
final public SalesUnit parmSalesUnit(SalesUnit _salesUnit = salesUnit)
{
    salesUnit = _salesUnit;
    return salesUnit;
}

/// <summary>
/// Parm method for Inventory dimension
/// </summary>
/// <param name = "_inventDimId">Invnetory dimension of the line</param>
/// <returns>Inventory dimension</returns>
final public InventDimId parmInventDimId(InventDimId _inventDimId = inventDimId)
{
    inventDimId = _inventDimId;
    return inventDimId;
}
